sealed class Counter {
    private readonly Channel<int> _mailbox = Channel.CreateBounded<int>(new BoundedChannelOptions(1_000) { SingleReader = true, FullMode = BoundedChannelFullMode.Wait });
    private int _count;
    public ValueTask TellAsync(int delta) => _mailbox.Writer.WriteAsync(delta);
    public async Task RunAsync() {                 // one reader loop = the actor
        await foreach (var delta in _mailbox.Reader.ReadAllAsync()) _count += delta;
    }
}

