public interface ICounterGrain : IGrainWithStringKey {
    Task AddAsync(int n);              // queued in the grain mailbox
    Task<int> GetAsync();
}
public sealed class CounterGrain : Grain, ICounterGrain {
    private int _count;                // per-activation state, no locks
    public Task AddAsync(int n) { _count += n; return Task.CompletedTask; }
    public Task<int> GetAsync() => Task.FromResult(_count);
}
